package com.app.service;
import com.app.dto.ExpenseCreateRequest; import com.app.dto.SocietyWorkOrderDtos.*; import com.app.entity.*; import com.app.exception.*; import com.app.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDate; import java.util.Set;
@Service @RequiredArgsConstructor public class SocietyWorkOrderExpenseService {
 private final SocietyWorkOrderRepository orders; private final ExpenseRepository expenses; private final ExpenseService expenseService; private final SocietyWorkOrderService workOrders; private final UserRepository users; private final SocietyWorkUpdateRepository updates; private final SocietyAuditEventRepository audit;
 @Transactional public WorkOrderDto request(Long accountId,Long userId,Long workOrderId,ExpenseRequest r){SocietyWorkOrder w=orders.findByAccountIdAndId(accountId,workOrderId).orElseThrow(()->new ResourceNotFoundException("Work order not found"));if(Set.of("VERIFIED","CANCELLED").contains(w.getStatus()))throw new ValidationException("Closed work orders cannot receive expense requests");ExpenseCreateRequest request=ExpenseCreateRequest.builder().expenseDate(LocalDate.now()).categoryId(r.getCategoryId()).expenseType(ExpenseType.SOCIETY_REGULAR).description(r.getDescription().trim()).amount(r.getAmount()).paymentMode(PaymentMode.CREDIT).vendorName(clean(r.getVendorName())).remarks("Requested from "+w.getWorkOrderNumber()).status(ExpenseStatus.SUBMITTED).build();var created=expenseService.createExpense(accountId,userId,request);Expense expense=expenses.findById(created.getId()).orElseThrow();expense.setWorkOrder(w);expense.setSourceReference("WORK_ORDER:"+workOrderId);expenses.save(expense);User actor=users.findById(userId).orElseThrow(()->new ResourceNotFoundException("User not found"));String note="Expense request #"+expense.getId()+" submitted for "+expense.getAmount();updates.save(SocietyWorkUpdate.builder().account(w.getAccount()).workOrder(w).createdBy(actor).updateType("EXPENSE_REQUESTED").previousStatus(w.getStatus()).newStatus(w.getStatus()).notes(note).build());audit.save(SocietyAuditEvent.builder().account(w.getAccount()).actor(actor).action("WORK_ORDER_EXPENSE_REQUESTED").entityType("WORK_ORDER").entityId(workOrderId).details("expenseId="+expense.getId()+"; amount="+expense.getAmount()).build());return workOrders.get(accountId,workOrderId);}
 @Transactional(readOnly=true) public java.util.List<ExpenseSummary> list(Long accountId,Long workOrderId){orders.findByAccountIdAndId(accountId,workOrderId).orElseThrow(()->new ResourceNotFoundException("Work order not found"));return expenses.findByAccountIdAndWorkOrderIdAndSoftDeletedFalseOrderByCreatedAtDesc(accountId,workOrderId).stream().map(x->ExpenseSummary.builder().id(x.getId()).categoryName(x.getCategory().getCategoryName()).description(x.getDescription()).amount(x.getAmount()).status(x.getStatus().name()).createdAt(x.getCreatedAt()).build()).toList();}
 private String clean(String s){return s==null||s.isBlank()?null:s.trim();}
}
